export const subscribeMockRemotePathsChange = (
  listener: (paths: string[]) => void,
) => {
  const handleStorage = (event: StorageEvent) => {
    if (event.key !== storageKeys.local.testMockRemotePaths.key) {
      return;
    }

    listener(readMockRemotePaths());
  };

  const handleCustomEvent = (event: Event) => {
    listener((event as CustomEvent<string[]>).detail ?? readMockRemotePaths());
  };

  window.addEventListener("storage", handleStorage);
  window.addEventListener(MOCK_REMOTE_CHANGED_EVENT, handleCustomEvent);

  return () => {
    window.removeEventListener("storage", handleStorage);
    window.removeEventListener(MOCK_REMOTE_CHANGED_EVENT, handleCustomEvent);
  };
};

