export function createEasterEgg(
  target: HTMLElement,
  callback: () => void,
  keySequence: readonly string[],
): () => void {
  const sequence = [...keySequence];
  if (sequence.length === 0) return () => {};
  const recent: string[] = [];

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.isComposing || event.repeat) return;
    if (event.target instanceof Element &&
        event.target.closest('input, textarea, [contenteditable]')) return;

    recent.push(event.key);
    if (recent.length > sequence.length) recent.shift();

    if (recent.length === sequence.length &&
        sequence.every((key, index) => key === recent[index])) {
      recent.length = 0;
      callback();
    }
  };

  target.addEventListener('keydown', handleKeyDown);
  return () => target.removeEventListener('keydown', handleKeyDown);
}

