// optionGenerator.mjs
export function generateOptions(endpoint) {
  const { domain, name, source, kind } = endpoint;
  if (!/^[A-Za-z_$][\w$]*$/.test(name)) {
    throw new Error('API 함수 이름을 확인하세요.');
  }
  if (kind !== 'query' && kind !== 'mutation') {
    throw new Error(`지원하지 않는 요청 종류: ${kind}`);
  }

  const key = JSON.stringify([domain, name]);
  const prefix = `import { ${name} } from ${JSON.stringify(source)};\n`;
  if (kind === 'mutation') {
    return prefix + `
export const ${name}MutationOptions = () => ({
  mutationKey: ${key},
  mutationFn: ${name},
});
`;
  }

  return prefix + `
export const ${name}QueryOptions = (
  input: Parameters<typeof ${name}>[0],
) => ({
  queryKey: [...${key}, input] as const,
  queryFn: () => ${name}(input),
});
`;
}

