import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';

export function ImageReadyContent({ children }: { children: ReactNode }) {
  const root = useRef<HTMLDivElement>(null);
  const [state, setState] = useState({ settled: false, failed: false });

  const check = useCallback(() => {
    const images = Array.from(root.current?.querySelectorAll('img') ?? []);
    setState({
      settled: images.every(image => image.complete),
      failed: images.some(image => image.complete && image.naturalWidth === 0),
    });
  }, []);

  useEffect(check, [check, children]);

  return (
    <section aria-busy={!state.settled}>
      {!state.settled && <p role="status">이미지를 불러오고 있습니다.</p>}
      {state.settled && state.failed && <p role="status">일부 이미지를 불러오지 못했습니다.</p>}
      <div
        ref={root}
        onLoadCapture={check}
        onErrorCapture={check}
        style={{ visibility: state.settled ? 'visible' : 'hidden' }}
      >
        {children}
      </div>
    </section>
  );
}

import { Children, type PropsWithChildren } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';

type StepProps = PropsWithChildren<{ step: number; showAll?: boolean }>;

export function Step({ children, step, showAll = false }: StepProps) {
  const reduceMotion = useReducedMotion();
  const steps = Children.toArray(children);

  if (showAll) return <>{children}</>;
  if (!Number.isInteger(step) || step < 0 || step >= steps.length) return null;

  return (
    <AnimatePresence mode="wait" initial={false}>
      <motion.div
        key={step}
        initial={{ opacity: 0, x: reduceMotion ? 0 : 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: reduceMotion ? 0 : -20 }}
        transition={{ duration: reduceMotion ? 0 : 0.3 }}
      >
        {steps[step]}
      </motion.div>
    </AnimatePresence>
  );
}

import { cloneElement, Fragment, type MouseEventHandler, type ReactElement } from 'react';

type ChildProps = {
  className?: string;
  onClick?: MouseEventHandler<HTMLElement>;
};

export function Slot({ children, className, onClick }: ChildProps & {
  children: ReactElement<ChildProps>;
}) {
  if (children.type === Fragment) {
    throw new Error('Slot requires a child that accepts DOM props.');
  }
  const childProps = children.props;
  return cloneElement(children, {
    className: [childProps.className, className].filter(Boolean).join(' ') || undefined,
    onClick: event => {
      childProps.onClick?.(event);
      if (!event.defaultPrevented) onClick?.(event);
    },
  });
}

import { useCallback, useMemo, useSyncExternalStore } from 'react';

const CHANGE_EVENT = 'app:local-storage-change';
const getServerSnapshot = () => null;

function readStorage(key: string): string | null {
  if (typeof window === 'undefined') return null;
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

export function useStorage<T>(
  key: string,
  initialValue: T,
  decode: (input: unknown) => T | undefined,
) {
  const getSnapshot = useCallback(() => readStorage(key), [key]);

  const subscribe = useCallback((notify: () => void) => {
    const handleStorage = (event: StorageEvent) => {
      try {
        if (event.storageArea !== window.localStorage) return;
      } catch {
        return;
      }
      if (event.key === key || event.key === null) notify();
    };

    const handleLocal = (event: Event) => {
      if (event instanceof CustomEvent && event.detail === key) notify();
    };

    window.addEventListener('storage', handleStorage);
    window.addEventListener(CHANGE_EVENT, handleLocal);
    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener(CHANGE_EVENT, handleLocal);
    };
  }, [key]);

  const raw = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
  const value = useMemo(() => {
    if (raw === null) return initialValue;
    try {
      const decoded = decode(JSON.parse(raw));
      return decoded === undefined ? initialValue : decoded;
    } catch {
      return initialValue;
    }
  }, [raw, decode, initialValue]);

  const setValue = useCallback((next: T | undefined): boolean => {
    if (typeof window === 'undefined') return false;
    try {
      if (next === undefined) {
        window.localStorage.removeItem(key);
      } else {
        const encoded = JSON.stringify(next);
        if (encoded === undefined) return false;
        window.localStorage.setItem(key, encoded);
      }
      window.dispatchEvent(new CustomEvent(CHANGE_EVENT, { detail: key }));
      return true;
    } catch {
      return false;
    }
  }, [key]);

  return [value, setValue] as const;
}

